using UnityEngine;
namespace LWS.TruckBuzkashi {public static class BuzRules {public static int Team(int slot)=>slot<3?0:1;public static bool EntireCargo(Bounds cargo,int team){float z=team==0?-49:49;return cargo.min.x>=-12&&cargo.max.x<=12&&cargo.min.z>=z-9&&cargo.max.z<=z+9&&cargo.min.y>=-.1f&&cargo.max.y<=9;}public static bool Breaks(int owner,int a,int b,float normalSpeed)=>owner>=0&&(owner==a||owner==b)&&Team(a)!=Team(b)&&normalSpeed>=2.3f;}}
